type Json=Record<string,unknown>;
type EcuConfig=CoreEcuConfig & Json;
interface MapConfig extends Json {rpm:number[];pressureBar:number[];values:number[][];kind:string;provenance:Json;valueUnit:string}
interface Observation extends Json {id:string;rpm:number;mapBar:number;observedLambda:number;steady:boolean;valid:boolean;split:'train'|'validation'}
interface Context {engine:EngineConfig;physical:PhysicalConfig}
interface Options {getContext():Context;applyPhysical(patch:Partial<PhysicalConfig>,reset?:boolean):void;applyEngine?(patch:Partial<EngineConfig>):void;getState():PowertrainState;reset():void;notify(message:string):void}
interface Candidate extends Json {id:string|number;lambdaTarget:number|null;sparkAdvanceDeg:number|null;dieselQuantityMg?:number|null;injectionAdvanceDeg?:number|null;actualQuantityMg?:number|null;minimumLambda?:number|null;torqueNm:number|null;powerKw:number|null;fuelMassFlowKgs:number|null;dutyFraction:number|null;valid:boolean;feasible:boolean;constraints?:unknown;error?:string|null}
