const dieselMapSlots:Record<string,string>={dieselFuelQuantity:'diesel.fuelQuantityMap',dieselMinimumLambda:'diesel.minimumLambdaMap',dieselInjectionAdvance:'diesel.injectionAdvanceMap'};
