   const coupling=(state as PowertrainState & {ecuCoupling?:Json|null}).ecuCoupling;q('ecu-coupling').textContent=coupling?`Acoplamento: ${String(coupling.couplingMode)} · diferença relativa entre combustível pedido ao ciclo e ciclo retido ${fmt(typeof coupling.fuelMassRelativeMismatch==='number'?coupling.fuelMassRelativeMismatch*100:undefined,2)}% · ${coupling.couplingQuantitativelyValid?'sem invalidade de acoplamento sinalizada':'resultado quantitativo limitado'} · ${Array.isArray(coupling.couplingFlags)?coupling.couplingFlags.join(', '):''}. O cálculo em cache não fecha o balanço energético do motor completo.`:'Sem resumo de acoplamento disponível neste passo.';
   captureStep(state,ecu);if(capturing)q('ecu-capture-status').textContent=`Capturando somente pontos elegíveis · ${captured.length}/1.000 pontos · inibições: ${Object.entries(captureRejected).map(([reason,count])=>`${reason} (${count})`).join(', ')||'nenhuma'} · lambda observada e multiplicador aplicado; sem ar real da planta. Papel desta sessão: ${captureRole==='train'?'ajuste':'verificação declarada'}. Condições sobrepostas não são uma validação independente.`;heatmap();
