 function switchMode(mode:string,demo=false){try{if(mode!=='portInjectionSpark'&&mode!=='directInjectionDiesel')throw new Error('Modo de combustão desconhecido.');const context=options.getContext(),next=structuredClone(getEcu());put(next,'combustionMode',mode);if(mode==='directInjectionDiesel'){const defaults=ecuRequest<EcuConfig>('normalizeEcuConfig',{engine:context.engine,config:{combustionMode:mode}});put(next,'diesel',structuredClone(at(defaults,'diesel')));}if(demo)next.enabled=true;cancel();capturing=false;proposedMap=undefined;fitContext='';q<HTMLButtonElement>('ecu-fit-apply').disabled=true;apply(next,true);if(demo){options.applyEngine?.({compression:16,redline:4500});options.reset();}q('ecu-status').textContent=demo?'Exemplo diesel aplicado: compressão 16:1 e limite 4.500 RPM. Injetor e combustão são hipóteses sintéticas; ensaio reiniciado.':'Modo alterado e ensaio reiniciado explicitamente. A geometria do motor foi preservada.';}catch(error){notifyError(error);refresh(true);}}
